  ('debc7784-7e58-53cf-9ccf-1ff5b19a91ce', null, (select id from public.skills where slug = 'write-g6-writing-with-evidence'), null, 'easy',
   $q$Which sentence best fills blank (5) to explain the evidence in sentences 3 and 4?$q$, $q$[{"text":"Kowalczyk also writes a few sentences about the color of the balloons.","is_correct":false,"misconception_token":"irrelevant-evidence"},{"text":"This means the balloons can measure high air that tools on the ground cannot reach.","is_correct":true},{"text":"Airplanes are one of the fastest ways to travel to other countries.","is_correct":false,"misconception_token":"off-topic-fact"},{"text":"This means that balloons are better than every other weather tool ever made.","is_correct":false,"misconception_token":"overgeneralization"}]$q$::jsonb, $q$This means the balloons can measure high air that tools on the ground cannot reach.$q$, $q$Sentences 3 and 4 say the sensors measure the air as the balloon climbs very high, so they gather information from places ground tools cannot reach. Saying balloons beat every other tool goes far beyond what the evidence shows.$q$, 'draft', 'f4d5d3d9-ad53-55b1-a094-6a30d5e02f64')
