  ('2a8cac6c-4798-5ca3-a7fb-eb53038d61ab', null, (select id from public.skills where slug = 'write-g7-argument-writing'), null, 'easy',
   $q$Which sentence would best fill the blank as sentence (2) and state the writer's claim?$q$, $q$[{"text":"Crestview should cover the library windows with bird-safe dot stickers to prevent these collisions.","is_correct":true},{"text":"The library wing was built last summer with very large glass windows.","is_correct":false,"misconception_token":"fact-not-claim"},{"text":"Birds are some of the most interesting animals that live near our school.","is_correct":false,"misconception_token":"topic-not-claim"},{"text":"Some birds fly into windows at our school, and some birds do not.","is_correct":false,"misconception_token":"no-position"}]$q$::jsonb, $q$Crestview should cover the library windows with bird-safe dot stickers to prevent these collisions.$q$, $q$Only this choice takes a clear position that the rest of the essay supports with reasons and evidence. The sentence about the library being built is a fact, not something a reader could argue for or against.$q$, 'draft', 'c42445ce-0a05-5ad9-ac2d-0786dfeff77e')
