  ('67901713-ab82-5b63-ad8e-d96436a4438a', null, (select id from public.skills where slug = 'write-g7-narrative-writing'), null, 'hard',
   $q$Which revision of sentence 7 best shows the narrator's feelings while keeping the first-person point of view?$q$, $q$[{"text":"You could hear the other groups cheering as their chocolate started to melt.","is_correct":false,"misconception_token":"shifts-to-second-person"},{"text":"Other groups cheered, and the narrator watched their chocolate turn soft.","is_correct":false,"misconception_token":"shifts-to-third-person"},{"text":"Tomas secretly wished that he had chosen a different partner for the project.","is_correct":false,"misconception_token":"shifts-point-of-view"},{"text":"Across the blacktop, other groups were already cheering, and my face grew hot.","is_correct":true}]$q$::jsonb, $q$Across the blacktop, other groups were already cheering, and my face grew hot.$q$, $q$The correct choice stays in the narrator's "I" voice and shows embarrassment through a physical detail. The choice about Tomas's secret wish is tempting, but a first-person narrator cannot know another character's hidden thoughts.$q$, 'draft', 'ea2b8934-ab36-5302-9e7e-5f661c696ea4')
