  ('d6a5db44-727b-5fb2-999e-92e442732c1d', null, (select id from public.skills where slug = 'write-g7-paragraph-transitions'), null, 'hard',
   $q$Which revision of sentence 11 would best conclude the whole passage by tying both paragraphs together?$q$, $q$[{"text":"All our careful planning and problem solving paid off when the class cheered for our clay turtle.","is_correct":true},{"text":"The rabbit's toothpick ears finally stayed up for the rest of the film.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Stop-motion films are popular with people of all ages around the world.","is_correct":false,"misconception_token":"too-broad"},{"text":"Next year, I hope our art unit will be about painting instead.","is_correct":false,"misconception_token":"off-topic-conclusion"}]$q$::jsonb, $q$All our careful planning and problem solving paid off when the class cheered for our clay turtle.$q$, $q$"Careful planning" points back to the steps in paragraph 1, and "problem solving" points back to the fixes in paragraph 2, so this sentence ties the passage together. The sentence about the rabbit's ears is too narrow because it covers only one fix.$q$, 'draft', '62392d98-87a5-55b9-91b5-1a490e30a0f4')
