  ('8d0ef512-9d1e-52bd-83b1-de1d8a491f73', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'easy',
   $q$Which sentence is a simple sentence?$q$, $q$[{"text":"After Priya painted the fence, her cousin cleaned the brushes.","is_correct":false,"misconception_token":"complex-as-simple"},{"text":"Priya painted the fence while her cousin cleaned the brushes.","is_correct":false,"misconception_token":"hidden-dependent-clause"},{"text":"Priya and her cousin painted the fence and cleaned the brushes.","is_correct":true},{"text":"Priya painted the fence, and her cousin cleaned the brushes.","is_correct":false,"misconception_token":"compound-as-simple"}]$q$::jsonb, $q$Priya and her cousin painted the fence and cleaned the brushes.$q$, $q$A simple sentence has one independent clause, and "Priya and her cousin painted the fence and cleaned the brushes" has just one clause with a compound subject and a compound verb. The "while" sentence looks simple because it has no comma, but "while her cousin cleaned the brushes" is a dependent clause, which makes it complex.$q$, 'draft', null)
