  ('d167dd40-5206-5e01-8cff-61d2f4b9fa13', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'easy',
   $q$Which sentence is a compound sentence?$q$, $q$[{"text":"The volcano model fizzed loudly and overflowed onto the table.","is_correct":false,"misconception_token":"compound-predicate-as-compound"},{"text":"The loud, fizzing volcano model did not overflow.","is_correct":false,"misconception_token":"simple-as-compound"},{"text":"The volcano model fizzed loudly, but it did not overflow.","is_correct":true},{"text":"Although the volcano model fizzed loudly, it did not overflow.","is_correct":false,"misconception_token":"complex-as-compound"}]$q$::jsonb, $q$The volcano model fizzed loudly, but it did not overflow.$q$, $q$"The volcano model fizzed loudly" and "it did not overflow" are two independent clauses joined by a comma and "but," which makes a compound sentence. The "fizzed loudly and overflowed" sentence has two verbs but only one subject and one clause, so it is simple.$q$, 'draft', null)
