  ('a9530e66-288d-5d52-ac89-2c30d7885782', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'easy',
   $q$Which sentence is a complex sentence?$q$, $q$[{"text":"The pond froze early, and the ducks flew south.","is_correct":false,"misconception_token":"compound-as-complex"},{"text":"The ducks flew south in the early winter.","is_correct":false,"misconception_token":"simple-as-complex"},{"text":"Because the pond froze early, the ducks flew south.","is_correct":true},{"text":"The pond froze early; the ducks flew south.","is_correct":false,"misconception_token":"semicolon-as-complex"}]$q$::jsonb, $q$Because the pond froze early, the ducks flew south.$q$, $q$A complex sentence has one independent clause and at least one dependent clause, and "Because the pond froze early" is a dependent clause attached to "the ducks flew south." The semicolon sentence joins two independent clauses, so it is compound.$q$, 'draft', null)
