  ('b2ac386a-0707-506d-915f-7e50256d4067', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'easy',
   $q$Read the sentences: "The class planted twelve oak trees. In the empty lot behind the gym." Which revision fixes the fragment?$q$, $q$[{"text":"The class planted twelve oak trees in the empty lot behind the gym.","is_correct":true},{"text":"The class planted twelve oak trees, they were in the empty lot behind the gym.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"The class planted twelve oak trees. In the empty lot, behind the gym.","is_correct":false,"misconception_token":"comma-does-not-fix-fragment"},{"text":"The class planted twelve oak trees; in the empty lot behind the gym.","is_correct":false,"misconception_token":"semicolon-before-phrase"}]$q$::jsonb, $q$The class planted twelve oak trees in the empty lot behind the gym.$q$, $q$"In the empty lot behind the gym" is a prepositional phrase, so it belongs inside the sentence it describes. A semicolon must join two independent clauses, so using one before a phrase does not fix the fragment.$q$, 'draft', null)
