  ('508a1aee-b6f8-5f58-bf97-0574b105b20e', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'medium',
   $q$Read the sentences: "Hoping to see the comet. Ines stayed up past midnight." Which revision fixes the fragment?$q$, $q$[{"text":"Hoping to see the comet; Ines stayed up past midnight.","is_correct":false,"misconception_token":"semicolon-before-phrase"},{"text":"Ines was hoping to see the comet, she stayed up past midnight.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"Hoping to see the comet, Ines stayed up past midnight.","is_correct":true},{"text":"Hoping to see the comet. Ines, stayed up past midnight.","is_correct":false,"misconception_token":"comma-does-not-fix-fragment"}]$q$::jsonb, $q$Hoping to see the comet, Ines stayed up past midnight.$q$, $q$"Hoping to see the comet" is a participial phrase with no subject or main verb, so it should introduce the sentence with a comma. The choice "Ines was hoping to see the comet, she stayed up past midnight" turns the phrase into a clause but then joins two independent clauses with only a comma, which is a comma splice.$q$, 'draft', null)
