  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('a9a58a94-aba2-53cb-9888-207fc4a5f982', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'medium',
   $q$Read the sentences: "Zainab is shy in large groups. She speaks confidently at the debate podium." Which combination best shows the contrast between the two ideas?$q$, $q$[{"text":"Although Zainab is shy in large groups, she speaks confidently at the debate podium.","is_correct":true},{"text":"Because Zainab is shy in large groups, she speaks confidently at the debate podium.","is_correct":false,"misconception_token":"cause-instead-of-contrast"},{"text":"Zainab is shy in large groups, she speaks confidently at the debate podium.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"Zainab is shy in large groups, and she speaks confidently at the debate podium.","is_correct":false,"misconception_token":"addition-hides-contrast"}]$q$::jsonb, $q$Although Zainab is shy in large groups, she speaks confidently at the debate podium.$q$, $q$"Although" signals that speaking confidently is surprising for someone who is shy, which is exactly the contrast. The "and" version is punctuated correctly but only adds one fact to another, so it hides the contrast.$q$, 'draft', null)
