  ('df9a9592-4655-5e5c-a522-2401ece6d9cc', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'hard',
   $q$Which sentence is a compound-complex sentence?$q$, $q$[{"text":"Because traffic was heavy, the pianist arrived late to the concert.","is_correct":false,"misconception_token":"complex-as-compound-complex"},{"text":"The pianist arrived late because traffic was heavy, but the concert still started on time.","is_correct":true},{"text":"The pianist, delayed by heavy traffic, arrived after the concert started.","is_correct":false,"misconception_token":"participial-phrase-as-clause"},{"text":"The pianist arrived late, and the concert started without her.","is_correct":false,"misconception_token":"compound-as-compound-complex"}]$q$::jsonb, $q$The pianist arrived late because traffic was heavy, but the concert still started on time.$q$, $q$The correct sentence has two independent clauses joined by "but" and one dependent clause, "because traffic was heavy." The "delayed by heavy traffic" sentence has a dependent clause ("after the concert started"), but "delayed by heavy traffic" is only a phrase, so it has just one independent clause and is complex.$q$, 'draft', null)
